{
  "items": [
    {
      "name": "MvPolynomial.smul_eval",
      "module_name": "Mathlib.Algebra.MvPolynomial.Eval",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type u_1} [inst : CommSemiring R] (x : σ → R) (p : MvPolynomial σ R) (s : R),\n  (MvPolynomial.eval x) (s • p) = s * (MvPolynomial.eval x) p"
    },
    {
      "name": "Polynomial.roots_smul_nonzero",
      "module_name": "Mathlib.Algebra.Polynomial.Roots",
      "kind": "theorem",
      "type": "∀ {R : Type u} {a : R} [inst : CommRing R] [inst_1 : IsDomain R] (p : Polynomial R), a ≠ 0 → (a • p).roots = p.roots"
    },
    {
      "name": "Polynomial.coeff_smul",
      "module_name": "Mathlib.Algebra.Polynomial.Coeff",
      "kind": "theorem",
      "type": "∀ {R : Type u} {S : Type v} [inst : Semiring R] [inst_1 : SMulZeroClass S R] (r : S) (p : Polynomial R) (n : ℕ),\n  (r • p).coeff n = r • p.coeff n"
    },
    {
      "name": "Mathlib.Tactic.ComputeDegree.coeff_smul",
      "module_name": "Mathlib.Tactic.ComputeDegree",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semiring R] {S : Type u_2} [inst_1 : SMulZeroClass S R] {n : ℕ} {a : S} {f : Polynomial R},\n  (a • f).coeff n = a • f.coeff n"
    },
    {
      "name": "Polynomial.roots_C_mul",
      "module_name": "Mathlib.Algebra.Polynomial.Roots",
      "kind": "theorem",
      "type": "∀ {R : Type u} {a : R} [inst : CommRing R] [inst_1 : IsDomain R] (p : Polynomial R),\n  a ≠ 0 → (Polynomial.C a * p).roots = p.roots"
    }
  ]
}
